505	  }, 0) / commonObjectIds.length;
506	  return {
507	    commonObjects: commonObjectIds.length,
508	    relativeOrderRetention: pairs === 0 ? 1 : Math.round((1 - inversions / pairs) * 1000) / 1000,
509	    meanDisplacement: Math.round(meanDisplacement * 100) / 100,
510	  };
