91	  graphOverride?: SemanticGraph;
92	}) {
93	  const architecture = detail?.architecture ?? EMPTY_ARCHITECTURE;
94	  const currentRevision = detail?.project.revision ?? graphOverride?.scope.revision ?? 1;
95	  const revisionOptions = useMemo(() => {
96	    if (!detail) return [currentRevision];
