142	  const pendingFlows = useMemo(() => architecture.flows.filter((flow) => flow.lifecycleStatus === "PENDING"), [architecture.flows]);
143	  const pendingFlowSteps = useMemo(() => architecture.flowSteps.filter((step) => step.lifecycleStatus === "PENDING"), [architecture.flowSteps]);
