145	  const entities = useMemo(() => latestModel(baseEntities, pendingEntities, (entity) => entity.entityKey, showChangeOverlay), [baseEntities, pendingEntities, showChangeOverlay]);
146	  const relations = useMemo(() => latestModel(baseRelations, pendingRelations, (relation) => relation.relationKey, showChangeOverlay), [baseRelations, pendingRelations, showChangeOverlay]);
147	  const flows = useMemo(() => latestModel(baseFlows, pendingFlows, (flow) => flow.flowKey, showChangeOverlay), [baseFlows, pendingFlows, showChangeOverlay]);
148	  const flowSteps = useMemo(() => latestModel(baseFlowSteps, pendingFlowSteps, (step) => `${step.flowKey}:${step.stepKey}`, showChangeOverlay), [baseFlowSteps, pendingFlowSteps, showChangeOverlay]);
149	
150	  const previousRevision = useMemo(() => {
151	    const index = revisionOptions.indexOf(viewRevision) - 1;
152	    return index >= 0 ? revisionOptions[index] : null;
153	  }, [revisionOptions, viewRevision]);
