"use client";

import {
  BaseEdge,
  EdgeLabelRenderer,
  getSmoothStepPath,
  type Edge,
  type EdgeProps,
} from "@xyflow/react";
import { useSmartEdgePath } from "@tisoap/react-flow-smart-edge";
import type { RelationshipEdgeData } from "./types";

export type ArchitectureFlowEdge = Edge<RelationshipEdgeData, "relationship">;

function roundedOrthogonalPath(points: Array<{ x: number; y: number }>, radius = 8) {
  if (points.length < 2) return "";
  let path = `M ${points[0].x} ${points[0].y}`;
  for (let index = 1; index < points.length - 1; index += 1) {
    const previous = points[index - 1];
    const current = points[index];
    const next = points[index + 1];
    const incomingLength = Math.hypot(current.x - previous.x, current.y - previous.y);
    const outgoingLength = Math.hypot(next.x - current.x, next.y - current.y);
    const corner = Math.min(radius, incomingLength / 2, outgoingLength / 2);
    if (!corner || (previous.x === current.x && current.x === next.x) || (previous.y === current.y && current.y === next.y)) {
      path += ` L ${current.x} ${current.y}`;
      continue;
    }
    const before = {
      x: current.x - ((current.x - previous.x) / incomingLength) * corner,
      y: current.y - ((current.y - previous.y) / incomingLength) * corner,
    };
    const after = {
      x: current.x + ((next.x - current.x) / outgoingLength) * corner,
      y: current.y + ((next.y - current.y) / outgoingLength) * corner,
    };
    path += ` L ${before.x} ${before.y} Q ${current.x} ${current.y} ${after.x} ${after.y}`;
  }
  const last = points.at(-1)!;
  return `${path} L ${last.x} ${last.y}`;
}

export default function RelationshipEdge(props: EdgeProps<ArchitectureFlowEdge>) {
  const smart = useSmartEdgePath({
    id: props.id,
    source: props.source,
    target: props.target,
    sourceX: props.sourceX,
    sourceY: props.sourceY,
    targetX: props.targetX,
    targetY: props.targetY,
    sourcePosition: props.sourcePosition,
    targetPosition: props.targetPosition,
    preset: "smoothstep",
    options: { gridRatio: 10, nodePadding: 18, borderRadius: 8 },
  });
  const fallback = getSmoothStepPath({
    sourceX: props.sourceX,
    sourceY: props.sourceY,
    sourcePosition: props.sourcePosition,
    targetX: props.targetX,
    targetY: props.targetY,
    targetPosition: props.targetPosition,
    borderRadius: 8,
  });
  const elkPath = props.data?.route?.points && props.data.route.points.length >= 2
    ? roundedOrthogonalPath(props.data.route.points)
    : "";
  const path = elkPath || (smart.route?.kind === "routed" ? smart.route.svgPathString : fallback[0]);
  const labelX = props.data?.route?.labelPoint?.x ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterX : fallback[1]);
  const labelY = props.data?.route?.labelPoint?.y ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterY : fallback[2]);
  const relationship = props.data?.relationship;
  const emphasis = props.data?.emphasis ?? "normal";
  const showLabel = emphasis === "active" || props.selected || props.data?.zoomLevel === "operational";
  const label = props.data?.flowPayload || relationship?.label || relationship?.relationshipType;
  const animate = emphasis === "active" && Boolean(props.data?.activeFlowName);

  return (
    <g className={`relationship-edge type-${relationship?.relationshipType ?? "dependency"} emphasis-${emphasis} ${props.selected ? "is-selected" : ""}`}>
      <BaseEdge
        id={props.id}
        interactionWidth={22}
        markerEnd={props.markerEnd}
        path={path}
        style={props.style}
      />
      {animate && (
        <circle className="flow-packet" r="4.5">
          <animateMotion dur="2.8s" path={path} repeatCount="indefinite" />
        </circle>
      )}
      {showLabel && label && (
        <EdgeLabelRenderer>
          <div
            className={`relationship-label nodrag nopan ${emphasis === "active" ? "active" : ""}`}
            style={{ transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)` }}
            title={relationship?.summary || relationship?.label}
          >
            {props.data?.flowSequence !== undefined && <b>{props.data.flowSequence}</b>}
            <span>{label}</span>
          </div>
        </EdgeLabelRenderer>
      )}
    </g>
  );
}

