168	  return [
169	    graph.version,
170	    ...graph.regions
171	      .map((region) => `r:${region.id}:${region.parentRegionId ?? "root"}:${region.order ?? 0}`)
172	      .sort(),
173	    ...graph.objects
174	      .map((object) => `o:${object.id}:${object.regionId}:${object.objectType}:${object.name}:${object.summary ?? ""}:${object.layoutHints?.order ?? 0}`)
175	      .sort(),
176	    ...graph.relationships
177	      .map((relationship) => `e:${relationship.id}:${relationship.sourceObjectId}:${relationship.targetObjectId}:${relationship.relationshipType}`)
178	      .sort(),
179	  ].join("|");
180	}
