export const SEMANTIC_GRAPH_VERSION = "canvas-engine-v1" as const;

export type SemanticObjectType = "service" | "agent" | "storage" | "external";

export type SemanticRelationshipType = "data" | "control" | "event" | "dependency" | "external";

export type SemanticState = {
  value: string;
  label: string;
  severity: "neutral" | "positive" | "attention" | "critical";
  source: "knowledge" | "runtime" | "change" | "lifecycle";
};

export type SemanticImportance = {
  level: "critical" | "high" | "normal" | "low";
  score: number;
};

export type SemanticPortRole = "input" | "output" | "upstream" | "downstream" | "event" | "control";

export type SemanticPortSide = "left" | "right" | "top" | "bottom";

export type SemanticLayoutHints = {
  order?: number;
  preferredLayer?: number;
  sourcePortRole?: SemanticPortRole;
  targetPortRole?: SemanticPortRole;
  sourcePortSide?: SemanticPortSide;
  targetPortSide?: SemanticPortSide;
  pinnedPosition?: { x: number; y: number };
};

export type SemanticRegion = {
  id: string;
  name: string;
  summary?: string;
  parentRegionId?: string;
  order?: number;
  importance: SemanticImportance;
  metadata: Record<string, unknown>;
};

export type SemanticObject = {
  id: string;
  name: string;
  summary?: string;
  objectType: SemanticObjectType;
  regionId: string;
  state: SemanticState;
  importance: SemanticImportance;
  metadata: Record<string, unknown>;
  layoutHints?: SemanticLayoutHints;
};

export type SemanticRelationship = {
  id: string;
  sourceObjectId: string;
  targetObjectId: string;
  relationshipType: SemanticRelationshipType;
  direction: "directed" | "bidirectional";
  label?: string;
  summary?: string;
  state: SemanticState;
  importance: SemanticImportance;
  metadata: Record<string, unknown>;
  layoutHints?: SemanticLayoutHints;
};

export type SemanticFlowStep = {
  id: string;
  objectId: string;
  sequence: number;
  role: string;
  title: string;
  inputs: string[];
  action: string;
  outputs: string[];
  stateReads: string[];
  stateWrites: string[];
  failureModes: string[];
  nextStepIds: string[];
  metadata: Record<string, unknown>;
};

export type SemanticFlow = {
  id: string;
  name: string;
  description?: string;
  objectIds: string[];
  relationshipIds: string[];
  steps: SemanticFlowStep[];
  state: SemanticState;
  importance: SemanticImportance;
  metadata: Record<string, unknown>;
};

export type SemanticScope = {
  projectId: string;
  revision: number;
  kind: "project" | "region" | "component" | "flow" | "runtime";
  rootRegionId?: string;
  source: "registry" | "fixture";
};

export type SemanticGraph = {
  id: string;
  version: typeof SEMANTIC_GRAPH_VERSION;
  name: string;
  regions: SemanticRegion[];
  objects: SemanticObject[];
  relationships: SemanticRelationship[];
  flows: SemanticFlow[];
  scope: SemanticScope;
  metadata: Record<string, unknown>;
};

export type SemanticGraphIndex = {
  regionById: Map<string, SemanticRegion>;
  objectById: Map<string, SemanticObject>;
  relationshipById: Map<string, SemanticRelationship>;
  flowById: Map<string, SemanticFlow>;
  incomingByObjectId: Map<string, SemanticRelationship[]>;
  outgoingByObjectId: Map<string, SemanticRelationship[]>;
  objectsByRegionId: Map<string, SemanticObject[]>;
  childRegionsByRegionId: Map<string | null, SemanticRegion[]>;
};

function append<K, V>(map: Map<K, V[]>, key: K, value: V) {
  const values = map.get(key) ?? [];
  values.push(value);
  map.set(key, values);
}

export function indexSemanticGraph(graph: SemanticGraph): SemanticGraphIndex {
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectById = new Map(graph.objects.map((object) => [object.id, object]));
  const relationshipById = new Map(graph.relationships.map((relationship) => [relationship.id, relationship]));
  const flowById = new Map(graph.flows.map((flow) => [flow.id, flow]));
  const incomingByObjectId = new Map<string, SemanticRelationship[]>();
  const outgoingByObjectId = new Map<string, SemanticRelationship[]>();
  const objectsByRegionId = new Map<string, SemanticObject[]>();
  const childRegionsByRegionId = new Map<string | null, SemanticRegion[]>();

  for (const relationship of graph.relationships) {
    append(outgoingByObjectId, relationship.sourceObjectId, relationship);
    append(incomingByObjectId, relationship.targetObjectId, relationship);
    if (relationship.direction === "bidirectional") {
      append(incomingByObjectId, relationship.sourceObjectId, relationship);
      append(outgoingByObjectId, relationship.targetObjectId, relationship);
    }
  }
  for (const object of graph.objects) append(objectsByRegionId, object.regionId, object);
  for (const region of graph.regions) append(childRegionsByRegionId, region.parentRegionId ?? null, region);

  return {
    regionById,
    objectById,
    relationshipById,
    flowById,
    incomingByObjectId,
    outgoingByObjectId,
    objectsByRegionId,
    childRegionsByRegionId,
  };
}

export function semanticGraphFingerprint(graph: SemanticGraph) {
  return [
    graph.version,
    ...graph.regions
      .map((region) => `r:${region.id}:${region.parentRegionId ?? "root"}:${region.order ?? 0}`)
      .sort(),
    ...graph.objects
      .map((object) => `o:${object.id}:${object.regionId}:${object.objectType}:${object.name}:${object.summary ?? ""}:${object.layoutHints?.order ?? 0}`)
      .sort(),
    ...graph.relationships
      .map((relationship) => `e:${relationship.id}:${relationship.sourceObjectId}:${relationship.targetObjectId}:${relationship.relationshipType}`)
      .sort(),
  ].join("|");
}

export function validateSemanticGraph(graph: SemanticGraph) {
  const errors: string[] = [];
  const duplicateIds = (ids: string[], kind: string) => {
    const seen = new Set<string>();
    for (const id of ids) {
      if (seen.has(id)) errors.push(`${kind} id is duplicated: ${id}`);
      seen.add(id);
    }
  };
  duplicateIds(graph.regions.map((region) => region.id), "Region");
  duplicateIds(graph.objects.map((object) => object.id), "Object");
  duplicateIds(graph.relationships.map((relationship) => relationship.id), "Relationship");
  duplicateIds(graph.flows.map((flow) => flow.id), "Flow");

  const regionIds = new Set(graph.regions.map((region) => region.id));
  const objectIds = new Set(graph.objects.map((object) => object.id));
  const relationshipIds = new Set(graph.relationships.map((relationship) => relationship.id));

  for (const region of graph.regions) {
    if (region.parentRegionId && !regionIds.has(region.parentRegionId)) errors.push(`Region ${region.id} references missing parent ${region.parentRegionId}`);
    const seen = new Set<string>([region.id]);
    let parentId = region.parentRegionId;
    while (parentId) {
      if (seen.has(parentId)) {
        errors.push(`Region hierarchy contains a cycle at ${region.id}`);
        break;
      }
      seen.add(parentId);
      parentId = graph.regions.find((candidate) => candidate.id === parentId)?.parentRegionId;
    }
  }
  for (const object of graph.objects) {
    if (!regionIds.has(object.regionId)) errors.push(`Object ${object.id} references missing region ${object.regionId}`);
  }
  for (const relationship of graph.relationships) {
    if (!objectIds.has(relationship.sourceObjectId)) errors.push(`Relationship ${relationship.id} references missing source ${relationship.sourceObjectId}`);
    if (!objectIds.has(relationship.targetObjectId)) errors.push(`Relationship ${relationship.id} references missing target ${relationship.targetObjectId}`);
  }
  for (const flow of graph.flows) {
    for (const objectId of flow.objectIds) if (!objectIds.has(objectId)) errors.push(`Flow ${flow.id} references missing object ${objectId}`);
    for (const relationshipId of flow.relationshipIds) if (!relationshipIds.has(relationshipId)) errors.push(`Flow ${flow.id} references missing relationship ${relationshipId}`);
    const stepIds = new Set(flow.steps.map((step) => step.id));
    if (stepIds.size !== flow.steps.length) errors.push(`Flow ${flow.id} contains duplicate step ids`);
    for (const step of flow.steps) {
      if (!objectIds.has(step.objectId)) errors.push(`Flow step ${step.id} references missing object ${step.objectId}`);
      for (const nextStepId of step.nextStepIds) if (!stepIds.has(nextStepId)) errors.push(`Flow step ${step.id} references missing next step ${nextStepId}`);
    }
  }
  return errors;
}

