.flow-lens { background: rgba(16,23,27,.98); border: 1px solid var(--map-line-strong); left: 12px; max-height: calc(100% - 24px); overflow-y: auto; padding: 14px; position: absolute; top: 12px; width: 316px; z-index: 25; }
