  .canvas-inspector { width: min(336px,88vw); }
  .canvas-statusbar span:nth-child(2), .canvas-statusbar span:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .canvas-inspector { transition: none; }
  .flow-packet { display: none; }
}

