.context-revision { border: 1px solid var(--map-line); color: var(--map-text-soft); padding: 2px 7px; }
.architecture-load-state { align-self: center; background: var(--map-panel); border-color: var(--map-line); color: var(--map-text); margin: auto; }
.architecture-load-state p { color: var(--map-text-soft); }

.canvas-shell .architecture-workbench {
  background: var(--map-bg);
  border: 0;
  border-radius: 0;
  box-shadow: none;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  height: calc(100vh - 46px);
  margin: 0;
  max-width: none;
  min-height: 0;
  overflow: hidden;
}
.architecture-workbench:fullscreen { --map-bg: #0b1013; --map-panel: #10171b; --map-line: rgba(187,207,211,.14); background: var(--map-bg); display: flex; flex-direction: column; }
.canvas-commandbar {
  align-items: center;
  background: rgba(13,20,24,.97);
  border-bottom: 1px solid var(--map-line);
  display: grid;
  gap: 14px;
  grid-template-columns: auto minmax(180px,340px) 1fr;
  min-height: 48px;
  padding: 5px 10px;
  z-index: 20;
}
.canvas-modes { align-items: center; display: flex; gap: 2px; }
.canvas-modes button, .canvas-command-actions button {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 3px;
  color: var(--map-text-muted);
  font-size: .8125rem;
  font-weight: 720;
  letter-spacing: .025em;
  min-height: 32px;
  padding: 4px 9px;
}
.canvas-modes button:hover, .canvas-command-actions button:hover { color: var(--map-text); }
.canvas-modes button.active, .canvas-command-actions button.active { background: rgba(155,210,193,.08); border-color: rgba(155,210,193,.2); color: var(--map-focus-strong); }
.canvas-modes button:disabled { opacity: .28; }
.canvas-modes b, .canvas-command-actions b { color: var(--map-focus); font-size: .8125rem; margin-left: 3px; }
.canvas-commandbar .canvas-search { position: relative; }
.canvas-commandbar .canvas-search input { background: rgba(255,255,255,.025); border: 1px solid var(--map-line); border-radius: 3px; color: var(--map-text); font-size: .8125rem; min-height: 32px; padding: 5px 9px; width: 100%; }
.canvas-commandbar .canvas-search input::placeholder { color: #65767b; }
.canvas-commandbar .canvas-search-results { background: #121a1f; border: 1px solid var(--map-line-strong); border-radius: 3px; box-shadow: none; left: 0; right: auto; top: 37px; width: 340px; }
.canvas-commandbar .canvas-search-results button { border-color: var(--map-line); color: var(--map-text); min-height: 42px; }
.canvas-commandbar .canvas-search-results button:hover { background: rgba(155,210,193,.05); }
.canvas-commandbar .canvas-search-results span { color: var(--map-focus); }
.canvas-command-actions { align-items: center; display: flex; gap: 2px; justify-content: flex-end; }
.canvas-command-actions button { border-left-color: var(--map-line); border-radius: 0; }

.canvas-shell .revision-timeline {
  background: #10171b;
  border-color: var(--map-line);
  color: var(--map-text-soft);
  grid-template-columns: auto auto minmax(160px,1fr) auto auto;
  min-height: 40px;
  padding: 4px 12px;
}
.canvas-shell .revision-timeline button { background: transparent; border: 1px solid var(--map-line); border-radius: 3px; color: var(--map-text-soft); min-height: 29px; }
.canvas-shell .revision-timeline small, .canvas-shell .revision-timeline strong { color: var(--map-text-soft); }
.canvas-shell .revision-timeline span { background: transparent; color: var(--map-text-muted); }
.canvas-shell .revision-timeline input { accent-color: var(--map-focus); }

.canvas-shell .canvas-stage { display: block; flex: 1 1 auto; height: auto; min-height: 0; overflow: hidden; position: relative; }
.architecture-workbench:fullscreen .canvas-stage { height: auto; }
.canvas-stage .architecture-canvas-kernel { background: var(--map-bg); }
.canvas-stage .react-flow__pane { cursor: grab; }
.canvas-stage .react-flow__pane:active { cursor: grabbing; }
.canvas-stage .react-flow__node { font-family: inherit; }
.canvas-stage .react-flow__node-region { pointer-events: none; }

.object-node { height: 100%; position: relative; width: 100%; }
.object-surface {
  background: rgba(19,28,33,.96);
  border: 1px solid rgba(186,205,209,.34);
  border-left: 3px solid #799793;
  color: var(--map-text);
  height: 100%;
  overflow: hidden;
  padding: 13px 15px 11px;
  position: relative;
  transition: background-color 130ms ease, border-color 130ms ease;
  width: 100%;
}
.object-node.type-agent .object-surface { border-left-style: dashed; }
.object-node.type-storage .object-surface { border-left-color: #8fa6b0; }
.object-node.type-external .object-surface { background: rgba(17,24,28,.88); border-left-color: #8a8f91; }
.object-node.is-selected .object-surface, .object-node.emphasis-primary .object-surface { background: #17242a; border-color: rgba(155,210,193,.78); border-left-color: var(--map-focus-strong); }
.object-node.is-selected .object-surface::after { border: 1px solid rgba(155,210,193,.34); content: ""; inset: 3px; pointer-events: none; position: absolute; }
.object-node.emphasis-related .object-surface { border-color: rgba(155,210,193,.43); }
.object-node.emphasis-context .object-surface { background: rgba(16,23,27,.83); border-color: rgba(186,205,209,.2); }
.object-node.emphasis-muted .object-surface { background: rgba(14,20,24,.55); border-color: rgba(186,205,209,.09); border-left-color: rgba(121,151,147,.22); }
.object-type-row { align-items: center; color: var(--map-text-muted); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; gap: 6px; letter-spacing: .06em; line-height: 1; text-transform: uppercase; }
.object-type-icon { align-items: center; display: inline-flex; height: 15px; justify-content: center; width: 15px; }
.object-type-icon svg { fill: none; height: 15px; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.35; width: 15px; }
.object-state { align-items: center; display: inline-flex; gap: 5px; margin-left: auto; text-transform: none; }
.object-state i, .inspector-identity dd i { background: currentColor; border-radius: 50%; display: inline-block; height: 5px; width: 5px; }
.object-state.severity-positive { color: #91b8ab; }
.object-state.severity-attention { color: var(--map-attention); }
.object-state.severity-critical { color: #d88982; }
.object-label { color: var(--map-text); display: block; font-size: .9375rem; font-weight: 680; letter-spacing: -.01em; line-height: 1.22; margin-top: 11px; overflow-wrap: anywhere; transform: scale(var(--label-scale)); transform-origin: left center; transition: color 130ms ease; }
.object-node.emphasis-muted .object-label { color: #98a5a8; }
.object-summary { color: var(--map-text-soft); display: -webkit-box; font-size: .8125rem; line-height: 1.45; margin-top: 7px; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.object-node.emphasis-muted .object-summary { color: #66777c; }
.object-metadata { align-items: center; bottom: 9px; color: var(--map-text-muted); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; justify-content: space-between; left: 15px; position: absolute; right: 15px; }
.object-flow-steps { align-items: center; display: flex; gap: 4px; left: 13px; position: absolute; right: 13px; top: -11px; }
.object-flow-steps span { align-items: center; background: #182a2c; border: 1px solid rgba(155,210,193,.5); color: var(--map-focus-strong); display: flex; font-size: .8125rem; gap: 4px; max-width: 94px; overflow: hidden; padding: 2px 5px; text-overflow: ellipsis; white-space: nowrap; }
.object-flow-steps b { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.object-flow-steps em { color: var(--map-focus); font-size: .8125rem; font-style: normal; }
.semantic-port { background: var(--map-focus) !important; border: 0 !important; height: 6px !important; opacity: 0; transition: opacity 100ms ease; width: 6px !important; }
.object-node:hover .semantic-port, .object-node.is-selected .semantic-port { opacity: .28; }
.object-node.zoom-landscape .object-type-row, .object-node.zoom-landscape .object-summary, .object-node.zoom-landscape .object-metadata { visibility: hidden; }
.object-node.zoom-architecture .object-summary, .object-node.zoom-architecture .object-metadata { display: none; }
.object-node.zoom-component .object-metadata { display: none; }

.canvas-region { background: rgba(87,109,114,.022); border: 1px solid rgba(159,179,184,.12); height: 100%; position: relative; width: 100%; }
.canvas-region.depth-1 { background: rgba(87,109,114,.014); border-style: dashed; }
.canvas-region.depth-2, .canvas-region.depth-3 { background: transparent; border-color: rgba(159,179,184,.08); }
.canvas-region.emphasis-active { border-color: rgba(155,210,193,.24); }
.canvas-region.emphasis-muted { border-color: rgba(159,179,184,.055); }
.canvas-region > header { align-items: baseline; color: var(--map-text-muted); display: flex; gap: 9px; left: 14px; position: absolute; top: 11px; }
.canvas-region > header span { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; letter-spacing: .08em; text-transform: uppercase; }
.canvas-region > header strong { color: #9eadb0; font-size: .8125rem; font-weight: 620; }
.canvas-region > header small { font-size: .8125rem; }
.canvas-region.zoom-landscape > header span, .canvas-region.zoom-landscape > header small { display: none; }
.canvas-region.emphasis-muted > header strong { color: #69787c; }

.relationship-edge .react-flow__edge-path { fill: none; stroke: #72858a; stroke-linecap: square; stroke-linejoin: round; stroke-width: 1.25; }
.relationship-edge.type-control .react-flow__edge-path { stroke-dasharray: 8 4; }
.relationship-edge.type-event .react-flow__edge-path { stroke-dasharray: 2 5; stroke-linecap: round; }
.relationship-edge.type-dependency .react-flow__edge-path { stroke: #66767b; stroke-dasharray: 5 4; }
.relationship-edge.type-external .react-flow__edge-path { stroke: #898f91; stroke-dasharray: 10 3 2 3; }
.relationship-edge.emphasis-related .react-flow__edge-path { stroke: #7ea79f; stroke-width: 1.45; }
.relationship-edge.emphasis-active .react-flow__edge-path, .relationship-edge.is-selected .react-flow__edge-path { stroke: var(--map-focus-strong); stroke-width: 2.35; }
.relationship-edge.emphasis-muted .react-flow__edge-path { stroke: #46555a; stroke-width: .9; }
.relationship-edge.emphasis-suppressed .react-flow__edge-path { opacity: .07; stroke-width: .8; }
.relationship-label { background: rgba(12,18,21,.96); border: 1px solid var(--map-line-strong); color: var(--map-text-soft); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; gap: 5px; max-width: 170px; padding: 2px 5px; pointer-events: all; position: absolute; }
.relationship-label.active { border-color: rgba(155,210,193,.55); color: var(--map-focus-strong); }
.relationship-label b { color: var(--map-focus); }
.relationship-label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.flow-packet { fill: var(--map-focus-strong); filter: none; pointer-events: none; }

.canvas-shell .architecture-controls { border: 1px solid var(--map-line) !important; border-radius: 2px !important; box-shadow: none !important; }
.canvas-shell .architecture-controls button { background: rgba(15,22,26,.94) !important; border-color: var(--map-line) !important; color: var(--map-text-soft) !important; fill: currentColor !important; }
.canvas-shell .architecture-minimap { background: rgba(15,22,26,.9) !important; border: 1px solid var(--map-line); border-radius: 2px; box-shadow: none; }
.canvas-reading-key { align-items: center; background: rgba(12,18,21,.88); border: 1px solid var(--map-line); bottom: 12px; display: flex; gap: 12px; left: 52px; padding: 5px 8px; position: absolute; z-index: 6; }
.canvas-reading-key span { align-items: center; color: var(--map-text-muted); display: flex; font-size: .8125rem; gap: 5px; }
.canvas-reading-key i { display: block; height: 6px; width: 12px; }
.canvas-reading-key .object-key { border: 1px solid #799793; }
.canvas-reading-key .relationship-key { border-top: 1px solid #72858a; height: 1px; }
.canvas-reading-key .trace-key { border-top: 2px solid var(--map-focus-strong); height: 1px; }
.canvas-reading-key em { border-left: 1px solid var(--map-line); color: #65767b; font-size: .8125rem; font-style: normal; padding-left: 10px; }
.canvas-layouting { background: rgba(11,16,19,.86); color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; font-weight: 600; letter-spacing: .03em; }
.canvas-layout-error { background: #2a2117; border: 1px solid rgba(225,179,107,.45); bottom: 42px; color: #e9c68f; font-size: .8125rem; left: 50%; padding: 7px 10px; position: absolute; transform: translateX(-50%); z-index: 28; }

.flow-lens { background: rgba(16,23,27,.98); border: 1px solid var(--map-line-strong); left: 12px; max-height: calc(100% - 24px); overflow-y: auto; padding: 14px; position: absolute; top: 12px; width: 316px; z-index: 25; }
.flow-lens > header { align-items: flex-start; display: flex; justify-content: space-between; }
.flow-lens > header div { display: grid; }
.flow-lens > header small { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; letter-spacing: .07em; }
.flow-lens > header strong { color: var(--map-text); font-size: .9375rem; margin-top: 2px; }
.flow-lens > header button, .inspector-heading > button { background: transparent; border: 1px solid var(--map-line); color: var(--map-text-muted); font-size: 1rem; min-height: 26px; width: 27px; }
.flow-lens > p { color: var(--map-text-muted); font-size: .8125rem; line-height: 1.55; margin: 10px 0 12px; }
.flow-lens-list { display: grid; }
.flow-lens-list > button { align-items: center; background: transparent; border: 0; border-top: 1px solid var(--map-line); color: var(--map-text); display: grid; gap: 8px; grid-template-columns: 8px 1fr auto; min-height: 58px; padding: 8px 2px; text-align: left; }
.flow-lens-list > button:hover { background: rgba(155,210,193,.035); }
.flow-lens-list > button > i { border: 1px solid #778a8f; border-radius: 50%; height: 7px; width: 7px; }
.flow-lens-list > button.active > i { background: var(--map-focus); border-color: var(--map-focus); }
.flow-lens-list > button > span { display: grid; min-width: 0; }
.flow-lens-list strong { font-size: .8125rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.flow-lens-list small { color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; }
.flow-lens-list > button > b { color: var(--map-focus); font-size: .8125rem; font-weight: 650; }
.flow-lens-empty { border-top: 1px solid var(--map-line); color: var(--map-text-muted); font-size: .8125rem; padding: 14px 2px; }

.canvas-inspector { background: rgba(15,22,26,.985); border-left: 1px solid var(--map-line-strong); bottom: 0; color: var(--map-text); overflow-y: auto; position: absolute; right: 0; top: 0; transform: translateX(101%); transition: transform 170ms ease; width: 336px; z-index: 24; }
.canvas-inspector.open { transform: translateX(0); }
.inspector-heading { align-items: flex-start; border-bottom: 1px solid var(--map-line); display: flex; justify-content: space-between; padding: 15px 15px 13px; }
.inspector-heading > div { display: grid; min-width: 0; }
.inspector-heading small { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; letter-spacing: .08em; text-transform: uppercase; }
.inspector-heading strong { font-size: .9375rem; line-height: 1.3; margin-top: 3px; overflow-wrap: anywhere; }
.inspector-identity { border-bottom: 1px solid var(--map-line); padding: 14px 15px; }
.inspector-identity > p { color: var(--map-text-soft); font-size: .8125rem; line-height: 1.6; }
.inspector-identity dl { display: grid; margin: 12px 0 0; }
.inspector-identity dl div, .inspector-facts div { border-top: 1px solid var(--map-line); display: grid; gap: 8px; grid-template-columns: 54px 1fr; padding: 7px 0; }
.inspector-identity dt, .inspector-facts dt { color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; }
.inspector-identity dd, .inspector-facts dd { color: var(--map-text-soft); font-size: .8125rem; margin: 0; overflow-wrap: anywhere; }
.inspector-identity dd { align-items: center; display: flex; gap: 5px; }
.inspector-identity dd .severity-positive { color: #91b8ab; }
.inspector-identity dd .severity-attention { color: var(--map-attention); }
.inspector-identity dd .severity-critical { color: #d88982; }
.inspector-focus-action { align-items: center; background: rgba(155,210,193,.08); border: 1px solid rgba(155,210,193,.3); color: var(--map-focus-strong); display: flex; font-size: .8125rem; justify-content: space-between; margin-top: 11px; min-height: 30px; padding: 4px 8px; width: 100%; }
.inspector-focus-action span { border: 1px solid var(--map-line-strong); color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; padding: 0 4px; }
.canvas-inspector details { border-bottom: 1px solid var(--map-line); padding: 0 15px 12px; }
.canvas-inspector summary { color: var(--map-text-soft); cursor: pointer; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; font-weight: 650; list-style: none; padding: 11px 0; }
.canvas-inspector summary::after { color: var(--map-text-muted); content: "+"; float: right; }
.canvas-inspector details[open] summary::after { content: "−"; }
.canvas-inspector details > p { color: var(--map-text-muted); font-size: .8125rem; line-height: 1.55; }
.inspector-facts { display: grid; margin: 0; }
.inspector-endpoints { align-items: center; display: grid; gap: 6px; grid-template-columns: 1fr auto 1fr; }
.inspector-endpoints button { background: rgba(255,255,255,.02); border: 1px solid var(--map-line); color: var(--map-text); display: grid; min-height: 48px; padding: 6px; text-align: left; }
.inspector-endpoints small { color: var(--map-text-muted); font-size: .8125rem; text-transform: uppercase; }
.inspector-endpoints strong { font-size: .8125rem; overflow-wrap: anywhere; }
.inspector-endpoints > span { color: var(--map-focus); }
.inspector-section-label { color: var(--map-text-muted); display: block; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; margin: 5px 0 3px; text-transform: uppercase; }
.inspector-relation-list, .inspector-object-list, .inspector-flow-list { display: grid; }
.inspector-relation-list button, .inspector-object-list button, .inspector-flow-list button { align-items: center; background: transparent; border: 0; border-top: 1px solid var(--map-line); color: var(--map-text-soft); display: grid; font-size: .8125rem; gap: 6px; min-height: 35px; padding: 5px 0; text-align: left; }
.inspector-relation-list button { grid-template-columns: 13px minmax(0,1fr); }
.inspector-relation-list small { color: var(--map-text-muted); grid-column: 2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.inspector-object-list button { grid-template-columns: 18px 1fr; }
.inspector-object-list b { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.inspector-flow-list button { grid-template-columns: 1fr auto; }
.inspector-flow-list span { color: var(--map-text-muted); }
.inspector-empty { color: var(--map-text-muted); font-size: .8125rem; padding: 4px 0; }
.inspector-flow-steps { display: grid; gap: 7px; list-style: none; margin: 0; padding: 0; }
.inspector-flow-steps li { align-items: flex-start; display: grid; gap: 7px; grid-template-columns: 20px 1fr; }
.inspector-flow-steps li > b { align-items: center; border: 1px solid rgba(155,210,193,.35); color: var(--map-focus); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; height: 20px; justify-content: center; }
.inspector-flow-steps li > div { display: grid; }
.inspector-flow-steps strong { color: var(--map-text-soft); font-size: .8125rem; }
.inspector-flow-steps span { color: var(--map-text-muted); font-size: .8125rem; }
.canvas-inspector pre { background: #0b1114; border: 1px solid var(--map-line); color: #8fa0a4; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; line-height: 1.55; max-height: 300px; overflow: auto; padding: 8px; white-space: pre-wrap; }

.canvas-shell .canvas-statusbar { background: #0d1418; border-color: var(--map-line); color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; min-height: 30px; padding: 4px 10px; }

@media (max-width: 900px) {
  .canvas-shell { grid-template-columns: 44px minmax(0,1fr); }
  .canvas-nav-rail { padding-left: 3px; padding-right: 3px; }
  .canvas-commandbar { gap: 5px; grid-template-columns: auto minmax(120px,1fr) auto; }
  .canvas-command-actions button:nth-last-child(n+3) { display: none; }
  .canvas-reading-key { display: none; }
  .canvas-inspector { width: min(336px,88vw); }
  .canvas-statusbar span:nth-child(2), .canvas-statusbar span:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .canvas-inspector { transition: none; }
  .flow-packet { display: none; }
}

