1	"use client";
2	
3	import type { SemanticFlow } from "./semantic-graph";
4	
5	export default function FlowPanel({
6	  activeFlowId,
7	  flows,
8	  onClose,
9	  onSelect,
10	}: {
11	  activeFlowId: string | null;
12	  flows: SemanticFlow[];
13	  onClose: () => void;
14	  onSelect: (flowId: string) => void;
15	}) {
16	  return (
17	    <aside className="flow-lens" aria-label="Project Flows">
18	      <header>
19	        <div><small>IOAYN · Learning Slice</small><strong>Trace a Flow</strong></div>
20	        <button aria-label="Close Flow list" onClick={onClose} type="button">×</button>
21	      </header>
22	      <p>Named behavior over the same Semantic Graph. A useful trace usually stays within 5–12 个节点.</p>
23	      <div className="flow-lens-list">
24	        {flows.map((flow) => {
25	          const active = flow.id === activeFlowId;
26	          return (
27	            <button className={active ? "active" : ""} key={flow.id} onClick={() => onSelect(flow.id)} type="button">
28	              <i aria-hidden="true" />
29	              <span><strong>{flow.name}</strong><small>{flow.steps.length} steps · {flow.objectIds.length} objects</small></span>
30	              <b>{active ? "Tracing" : "Trace"}</b>
31	            </button>
32	          );
33	        })}
34	        {flows.length === 0 && <div className="flow-lens-empty">No Flow has been declared for this scope.</div>}
35	      </div>
36	    </aside>
37	  );
38	}
