export type TraceCorridorTransition = {
  relationshipId: string;
  fromStepId: string;
  toStepId: string;
  sequence: number;
  payload: string;
  detail: string;
};

export type TraceCorridor = {
  flowId: string;
  steps: Array<SemanticFlowStep & { isEntry: boolean; isExit: boolean }>;
  transitions: TraceCorridorTransition[];
  relationshipIds: string[];
};

export function traceCorridor(graph: SemanticGraph, flowId: string | null | undefined): TraceCorridor | null {
  const flow = graph.flows.find((candidate) => candidate.id === flowId);
  if (!flow) return null;
  const steps = [...flow.steps].sort((left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id));
  const stepById = new Map(steps.map((step) => [step.id, step]));
  // entry = step with no incoming next-step references within flow; exit = no next steps
  const referenced = new Set<string>();
  for (const step of steps) for (const next of step.nextStepIds) referenced.add(next);
  const ordered = steps.map((step) => ({
    ...step,
    isEntry: !referenced.has(step.id),
    isExit: step.nextStepIds.length === 0,
  }));
  const transitions: TraceCorridorTransition[] = [];
  for (const step of ordered) {
    for (const nextId of step.nextStepIds) {
      const next = stepById.get(nextId);
      if (!next) continue;
      const relationship = graph.relationships.find((candidate) =>
        candidate.sourceObjectId === step.objectId && candidate.targetObjectId === next.objectId)
        ?? graph.relationships.find((candidate) =>
          candidate.sourceObjectId === next.objectId && candidate.targetObjectId === step.objectId);
      const payload = step.outputs.length > 0 ? step.outputs.join(" + ") : next.inputs.join(" + ");
      transitions.push({
        relationshipId: relationship?.id ?? `${step.id}->${next.id}`,
        fromStepId: step.id,
        toStepId: next.id,
        sequence: step.sequence,
        payload,
        detail: `${step.title} → ${next.title}`,
      });
    }
  }
  ...
}
