import { MarkerType, type Edge, type Node } from "@xyflow/react";
import {
  corridorTransitionBetween,
  regionReadingSummary,
  traceCorridor,
  visibleObjectIds,
  type CanvasViewModel,
} from "./interaction";
import type { CanvasLayout } from "./layout";
import { indexSemanticGraph, type SemanticGraph } from "./semantic-graph";
import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData } from "./types";

export type CanvasObjectNode = Node<ObjectNodeData, "object">;
export type CanvasRegionNode = Node<RegionNodeData, "region">;
export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
  return `${role}-${side}`;
}

/**
 * Routes dropped by Region packing are re-routed by the obstacle-aware edge
 * renderer; picking handles from the relative geometry keeps those routes
 * reading vertically between packed Region rows and horizontally inside rows.
 */
function routedSides(
  layout: CanvasLayout,
  sourceObjectId: string,
  targetObjectId: string,
  fallback: { sourceSide: "left" | "right" | "top" | "bottom"; targetSide: "left" | "right" | "top" | "bottom" },
) {
  const source = layout.objectRects[sourceObjectId];
  const target = layout.objectRects[targetObjectId];
  if (!source || !target) return fallback;
  const dx = target.x + target.width / 2 - (source.x + source.width / 2);
  const dy = target.y + target.height / 2 - (source.y + source.height / 2);
  if (Math.abs(dy) > Math.abs(dx)) return { sourceSide: dy > 0 ? "bottom" : "top", targetSide: dy > 0 ? "top" : "bottom" } as const;
  return { sourceSide: dx > 0 ? "right" : "left", targetSide: dx > 0 ? "left" : "right" } as const;
}

