"use client";

import type { CSSProperties } from "react";
import type { Node, NodeProps } from "@xyflow/react";
import { labelCompensationScale } from "./interaction";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, childRegionCount, summary, depth } = data;
  const labelScale = labelCompensationScale(zoom, depth === 0 ? 15 : 13, depth === 0 ? 4.5 : 3.2);
  const keyLine = summary.keyObjectNames.length > 0
    ? summary.keyObjectNames.join(" · ")
    : "No key objects declared";
  return (
    <section
      aria-label={`Region ${region.name}，${objectCount} objects`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--label-scale": labelScale } as CSSProperties}
    >
      <header>
        <div className="canvas-region-title">
          <span>Region</span>
          <strong>{region.name}</strong>
          <small>{objectCount} objects{childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""} · {summary.crossRegionLinkCount} links</small>
        </div>
        {zoomLevel === "landscape" && (
          <p className="canvas-region-keys" title={keyLine}>{keyLine}</p>
        )}
      </header>
    </section>
  );
}

