import {
  indexSemanticGraph,
  type SemanticFlow,
  type SemanticGraph,
  type SemanticObject,
  type SemanticRegion,
  type SemanticRelationship,
  type SemanticState,
} from "./semantic-graph";
import type { CanvasSelection } from "./interaction";

type InspectorBase = {
  id: string;
  title: string;
  typeLabel: string;
  summary: string;
  state: SemanticState;
  location: string;
  raw: Record<string, unknown>;
};

export type ObjectInspectorBinding = InspectorBase & {
  kind: "object";
  object: SemanticObject;
  region?: SemanticRegion;
  incoming: SemanticRelationship[];
  outgoing: SemanticRelationship[];
  flows: SemanticFlow[];
};

export type RelationshipInspectorBinding = InspectorBase & {
