  SMALL_CANVAS_FIXTURE,
} = await import("../app/architecture/fixtures.ts");
const {
  ARCHITECTURE_ZOOM_FLOOR,
  MIN_MEANINGFUL_TEXT_PX,
  corridorTransitionBetween,
  deriveCanvasView,
  labelCompensationScale,
  regionReadingSummary,
  semanticZoomLevel,
  traceCorridor,
  visibleObjectIds,
} = await import("../app/architecture/interaction.ts");
const { bindInspector } = await import("../app/architecture/inspector-binding.ts");
const { layoutSemanticGraph, measureLayoutStability, packTopLevelRegions } = await import("../app/architecture/layout.ts");
const { adaptArchitectureToSemanticGraph } = await import("../app/architecture/semantic-adapter.ts");
const { validateSemanticGraph } = await import("../app/architecture/semantic-graph.ts");

function topAncestorRegionId(graph, regionId) {
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  let cursor = regionById.get(regionId);
  const seen = new Set();
  while (cursor?.parentRegionId && !seen.has(cursor.id)) {
    seen.add(cursor.id);
    cursor = regionById.get(cursor.parentRegionId);
  }
  return cursor?.id ?? null;
}

function crossesTopLevelRegion(graph, relationship) {
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectById = new Map(graph.objects.map((object) => [object.id, object]));
  const sourceRegionId = regionById.get(objectById.get(relationship.sourceObjectId)?.regionId ?? "")?.id;
  const targetRegionId = regionById.get(objectById.get(relationship.targetObjectId)?.regionId ?? "")?.id;
  return topAncestorRegionId(graph, sourceRegionId) !== topAncestorRegionId(graph, targetRegionId);
}

