test("top-level Regions compose two-dimensionally instead of one strip", { timeout: 60_000 }, async () => {
  for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
    const layout = await layoutSemanticGraph(graph);
    const topLevelRects = graph.regions
      .filter((region) => !region.parentRegionId)
      .map((region) => layout.regionRects[region.id])
      .filter(Boolean);
    assert.ok(topLevelRects.length >= 2, `${name} fixture exercises multiple top-level Regions`);

    for (let leftIndex = 0; leftIndex < topLevelRects.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < topLevelRects.length; rightIndex += 1) {
        assert.equal(overlap(topLevelRects[leftIndex], topLevelRects[rightIndex], 8), false, `${name}: packed Regions must not overlap`);
      }
    }

    const rowTops = [...new Set(topLevelRects.map((rect) => Math.round(rect.y / 10)))].sort((left, right) => left - right);
    assert.ok(rowTops.length >= 2, `${name}: top-level Regions must occupy more than one row, received ${rowTops.length}`);
    for (const rowTop of rowTops) {
      const row = topLevelRects.filter((rect) => Math.round(rect.y / 10) === rowTop);
      const uniqueTops = new Set(row.map((rect) => rect.y));
      assert.equal(uniqueTops.size, 1, `${name}: Regions in one row must share a top edge`);
    }
    const aspect = layout.width / layout.height;
    assert.ok(aspect > .45 && aspect < 3, `${name}: packed map aspect should stay viewport-like, received ${aspect.toFixed(2)}`);
  }

  const unpacked = await (async () => {
    const { packTopLevelRegions: pack } = await import("../app/architecture/layout.ts");
    const raw = await layoutSemanticGraph(SMALL_CANVAS_FIXTURE);
    const packed = pack(SMALL_CANVAS_FIXTURE, raw);
    assert.ok(packed.rowCount >= 2, "Small fixture should pack into multiple rows");
    assert.equal(packed.topLevelRegionCount, SMALL_CANVAS_FIXTURE.regions.filter((region) => !region.parentRegionId).length);
    return raw;
  })();
  assert.ok(unpacked.width > 0, "Layout must produce geometry for the packing input");
});

test("default camera holds Architecture density with readable screen-space text", () => {
  assert.ok(ARCHITECTURE_ZOOM_FLOOR >= .5, "The default fit must not fall below a readable zoom floor");
  assert.equal(semanticZoomLevel(ARCHITECTURE_ZOOM_FLOOR), "architecture", "The default fit must land in the Architecture density band");
  const minimumObjectWidth = 232;
  assert.ok(minimumObjectWidth * ARCHITECTURE_ZOOM_FLOOR >= 120, "Objects must stay a readable screen-space size at the default camera");
  const labelPx = 15;
  const defaultScreenText = labelCompensationScale(ARCHITECTURE_ZOOM_FLOOR, labelPx) * labelPx * ARCHITECTURE_ZOOM_FLOOR;
  assert.ok(defaultScreenText + .01 >= MIN_MEANINGFUL_TEXT_PX, `Default view labels must stay ≥ ${MIN_MEANINGFUL_TEXT_PX}px on screen, received ${defaultScreenText.toFixed(1)}`);
  assert.equal(labelCompensationScale(1.2, labelPx), 1, "Zoomed-in labels need no compensation");
  assert.ok(labelCompensationScale(.1, labelPx) <= 4.5, "Compensation must stay bounded on extreme zoom-out");
  assert.equal(semanticZoomLevel(.3), "landscape");
  assert.equal(semanticZoomLevel(1.4), "operational");
});

test("Trace renders an ordered corridor from entry to result", () => {
  const flow = COMPLEX_CANVAS_FIXTURE.flows[0];
  const corridor = traceCorridor(COMPLEX_CANVAS_FIXTURE, flow.id);
  assert.ok(corridor, "A named Flow must produce a corridor");
  assert.deepEqual(corridor.steps.map((step) => step.sequence), [...corridor.steps.keys()].map((index) => index + 1), "Corridor steps must be sequence-ordered");
  assert.equal(corridor.steps[0].isEntry, true, "The first corridor step is the entry");
  assert.equal(corridor.steps.at(-1).isExit, true, "The last corridor step is the result");
  assert.ok(corridor.steps.filter((step) => step.isEntry).length >= 1);
  assert.equal(corridor.transitions.length, corridor.steps.length - 1, "A linear Flow has one transition per consecutive step pair");
  for (const transition of corridor.transitions) {
    assert.ok(transition.payload.length > 0, "Every transition must name what it hands over");
    assert.ok(transition.relationshipId.length > 0);
  }
  const forward = corridorTransitionBetween(corridor, corridor.transitions[0].fromObjectId, corridor.transitions[0].toObjectId);
  assert.equal(forward?.relationshipId, corridor.transitions[0].relationshipId);
  const reverse = corridorTransitionBetween(corridor, corridor.transitions[0].toObjectId, corridor.transitions[0].fromObjectId);
  assert.equal(reverse?.relationshipId, corridor.transitions[0].relationshipId, "Corridor transitions are direction-agnostic lookups");
  const isolated = COMPLEX_CANVAS_FIXTURE.objects.find((object) => !COMPLEX_CANVAS_FIXTURE.relationships.some((relationship) =>
    relationship.sourceObjectId === object.id || relationship.targetObjectId === object.id));
  assert.ok(isolated, "Complex fixture keeps an isolated object");
  assert.equal(corridorTransitionBetween(corridor, corridor.steps[0].objectId, isolated.id), null, "Unrelated pairs have no corridor transition");
  assert.equal(traceCorridor(COMPLEX_CANVAS_FIXTURE, "missing-flow"), null);
});

test("Region reading summaries stay meaningful when Landscape hides objects", () => {
  const topRegions = MEDIUM_CANVAS_FIXTURE.regions.filter((region) => !region.parentRegionId);
  const withKeys = topRegions.filter((region) => regionReadingSummary(MEDIUM_CANVAS_FIXTURE, region.id).keyObjectNames.length > 0);
  assert.ok(withKeys.length > 0, "At least one top-level Region must surface key object names");
  for (const region of topRegions) {
    const summary = regionReadingSummary(MEDIUM_CANVAS_FIXTURE, region.id);
    const descendantRegionIds = new Set(MEDIUM_CANVAS_FIXTURE.regions
      .filter((candidate) => topAncestorRegionId(MEDIUM_CANVAS_FIXTURE, candidate.id) === region.id)
      .map((candidate) => candidate.id));
    const expectedObjects = MEDIUM_CANVAS_FIXTURE.objects.filter((object) => descendantRegionIds.has(object.regionId)).length;
    assert.equal(summary.objectCount, expectedObjects, "Region summaries must count the whole subtree");
    const importantNames = new Set(MEDIUM_CANVAS_FIXTURE.objects
      .filter((object) => descendantRegionIds.has(object.regionId) && (object.importance.level === "critical" || object.importance.level === "high"))
      .map((object) => object.name));
    for (const name of summary.keyObjectNames) assert.ok(importantNames.has(name), "Key object names must come from important objects in the subtree");
    assert.ok(summary.keyObjectNames.length <= 3, "Key object lists stay bounded");
  }
  const totals = topRegions.reduce((accumulator, region) => {
    const summary = regionReadingSummary(MEDIUM_CANVAS_FIXTURE, region.id);
    return { internal: accumulator.internal + summary.internalLinkCount, cross: accumulator.cross + summary.crossRegionLinkCount };
  }, { internal: 0, cross: 0 });
  assert.equal(totals.internal + totals.cross / 2, MEDIUM_CANVAS_FIXTURE.relationships.length, "Link counts must partition the relationship budget");
});

test("hovering previews relationships without leaving Browse mode", () => {
  const hub = SMALL_CANVAS_FIXTURE.objects[0];
  const incident = SMALL_CANVAS_FIXTURE.relationships.filter((relationship) =>
    relationship.sourceObjectId === hub.id || relationship.targetObjectId === hub.id);
  assert.ok(incident.length > 0, "The hub object must have relationships to preview");
  const view = deriveCanvasView(SMALL_CANVAS_FIXTURE, {
    mode: "browse",
    selection: null,
    activeFlowId: null,
    zoom: .7,
    searchQuery: "",
    hoveredObjectId: hub.id,
