  const totals = topRegions.reduce((accumulator, region) => {
    const summary = regionReadingSummary(MEDIUM_CANVAS_FIXTURE, region.id);
    return { internal: accumulator.internal + summary.internalLinkCount, cross: accumulator.cross + summary.crossRegionLinkCount };
  }, { internal: 0, cross: 0 });
