const PACKING = { aspect: 1.55, columnGap: 68, rowGap: 76, margin: 42 };

export type RegionPackingResult = {
  layout: CanvasLayout;
  topLevelRegionCount: number;
  rowCount: number;
};

/**
 * ELK lays the top-level Regions out along one axis, so a Region chain becomes a
 * long strip. Packing re-composes the top-level Regions into rows around a
 * viewport-like aspect ratio while every Region subtree keeps its internal ELK
 * geometry. Relationships between objects of the same top-level Region keep
 * their orthogonal ELK route (shifted); cross-Region relationships drop their
 * route so the renderer's obstacle-aware router can follow the packed map.
 */
export function packTopLevelRegions(
  graph: SemanticGraph,
  layout: CanvasLayout,
  options: { targetAspect?: number } = {},
): RegionPackingResult {
  const aspect = options.targetAspect ?? PACKING.aspect;
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectById = new Map(graph.objects.map((object) => [object.id, object]));
  const topLevel = graph.regions
    .filter((region) => !region.parentRegionId)
    .map((region) => ({ region, rect: layout.regionRects[region.id] }))
    .filter((entry): entry is { region: SemanticRegion; rect: RegionLayoutRect } => Boolean(entry.rect));
  if (topLevel.length <= 1) {
    return { layout, topLevelRegionCount: topLevel.length, rowCount: 1 };
  }

  const ordered = topLevel
    .sort((left, right) => left.rect.y - right.rect.y || left.rect.x - right.rect.x || left.region.id.localeCompare(right.region.id));

  const totalArea = ordered.reduce(
    (sum, entry) => sum + (entry.rect.width + PACKING.columnGap) * (entry.rect.height + PACKING.rowGap),
    0,
  );
  const widestRegion = Math.max(...ordered.map((entry) => entry.rect.width));
  const targetWidth = Math.max(widestRegion, Math.round(Math.sqrt(totalArea * aspect)));

  const placements = new Map<string, { x: number; y: number }>();
  let cursorX = PACKING.margin;
  let rowTop = PACKING.margin;
  let rowHeight = 0;
  let rowCount = 1;
  for (const entry of ordered) {
    if (cursorX > PACKING.margin && cursorX + entry.rect.width > PACKING.margin + targetWidth) {
      rowTop += rowHeight + PACKING.rowGap;
      cursorX = PACKING.margin;
      rowHeight = 0;
      rowCount += 1;
    }
    placements.set(entry.region.id, { x: cursorX, y: rowTop });
    cursorX += entry.rect.width + PACKING.columnGap;
    rowHeight = Math.max(rowHeight, entry.rect.height);
  }

  const topAncestorId = new Map<string, string>();
  for (const region of graph.regions) {
    let cursor = region;
    const seen = new Set<string>([region.id]);
    while (cursor.parentRegionId) {
      const parent = regionById.get(cursor.parentRegionId);
      if (!parent || seen.has(parent.id)) break;
      seen.add(parent.id);
      cursor = parent;
    }
    topAncestorId.set(region.id, cursor.id);
  }

