// Local-only harness: serves the vinext production build through Node so the
// Architecture Canvas can be reviewed in a real browser without Cloudflare.
// Not part of the app; used for run evidence screenshots.
import { register } from "node:module";
import http from "node:http";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

register(new URL("../tests/cloudflare-loader.mjs", import.meta.url), import.meta.url);

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const clientRoot = path.join(root, "dist", "client");

const workerUrl = new URL("../dist/server/index.js", import.meta.url);
workerUrl.searchParams.set("test", `${process.pid}-${Date.now()}`);
const { default: worker } = await import(workerUrl.href);

const MIME = {
  ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css",
  ".html": "text/html", ".svg": "image/svg+xml", ".png": "image/png",
  ".ico": "image/x-icon", ".json": "application/json", ".map": "application/json",
  ".woff2": "font/woff2", ".webp": "image/webp",
};

async function staticResponse(pathname) {
  const relative = decodeURIComponent(pathname).replace(/^\/+/, "");
  const candidates = relative === "" ? ["index.html"] : [relative, path.join(relative, "index.html")];
  for (const candidate of candidates) {
    const resolved = path.join(clientRoot, candidate);
    if (!resolved.startsWith(clientRoot)) continue;
    try {
      const body = await readFile(resolved);
      return new Response(body, { headers: { "content-type": MIME[path.extname(resolved)] ?? "application/octet-stream" } });
    } catch {
      // try next candidate
    }
  }
  return new Response("Not found", { status: 404 });
}

const server = http.createServer((req, res) => {
  const request = new Request(`http://localhost:${PORT}${req.url}`, {
    method: req.method,
    headers: req.headers,
    body: req.method === "GET" || req.method === "HEAD" ? undefined : req,
    duplex: "half",
  });
  void worker
    .fetch(request, {
      ASSETS: { fetch: (assetRequest) => staticResponse(new URL(assetRequest.url).pathname) },
    }, {
      waitUntil() {},
      passThroughOnException() {},
    })
    .then(async (response) => {
      res.writeHead(response.status, Object.fromEntries(response.headers.entries()));
      const buffer = Buffer.from(await response.arrayBuffer());
      res.end(buffer);
    })
    .catch((error) => {
      res.writeHead(500, { "content-type": "text/plain" });
      res.end(String(error?.stack ?? error));
    });
});

const PORT = Number(process.env.PORT ?? 4311);
server.listen(PORT, "127.0.0.1", () => {
  console.log(`serving dist on http://127.0.0.1:${PORT}`);
});

