  const bar = document.querySelector(".canvas-statusbar");
  const objects = [...document.querySelectorAll(".object-node")];
  const regions = [...document.querySelectorAll(".canvas-region")];
  const transform = document.querySelector(".react-flow__viewport")?.style.transform;
  const stage = document.querySelector(".canvas-stage");
  const labels = objects.slice(0, 5).map((node) => {
    const label = node.querySelector(".object-label");
    const rect = label?.getBoundingClientRect();
    return { text: label?.textContent, screenFontPx: rect ? getComputedStyle(label).fontSize : null, scale: label?.style.transform };
  });
  return {
    statusbar: bar?.textContent,
    viewportTransform: transform,
    objectCount: objects.length,
    regionCount: regions.length,
    regionHeaders: regions.slice(0, 4).map((region) => region.querySelector("header")?.textContent),
    stageBox: stage ? { w: stage.getBoundingClientRect().width, h: stage.getBoundingClientRect().height } : null,
    sampleLabels: labels,
  };
}

