                <b>{step.sequence}</b>{step.isEntry ? "Entry" : step.isExit ? "Result" : step.title}
              </span>
            ))}
            {flowSteps.length > 3 && <em>+{flowSteps.length - 3}</em>}
          </div>
        )}
      </div>
