async () => {
  const select = document.querySelector("select[aria-label='Stress fixture']");
  select.value = "complex";
  select.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 3500));
  const traceButton = [...document.querySelectorAll(".canvas-modes button")].find((button) => button.textContent.includes("Trace"));
  traceButton.click();
  await new Promise((resolve) => setTimeout(resolve, 300));
  document.querySelector(".flow-lens-list button").click();
  await new Promise((resolve) => setTimeout(resolve, 1800));
  const kernel = document.querySelector(".architecture-canvas-kernel")?.getBoundingClientRect();
  const labels = [...document.querySelectorAll(".relationship-label")].map((label) => {
    const box = label.getBoundingClientRect();
    const inner = label.firstElementChild?.getBoundingClientRect();
    return { text: label.textContent, x: Math.round(box.x), y: Math.round(box.y), screenH: inner ? Math.round(inner.height) : null, visible: box.x > 0 && box.x < (kernel?.width ?? 0) && box.y > 0 && box.y < (kernel?.height ?? 0) };
  });
  const chips = [...document.querySelectorAll(".object-flow-steps")].map((chip) => {
    const box = chip.getBoundingClientRect();
    return { text: chip.textContent, x: Math.round(box.x), y: Math.round(box.y), visible: box.x > 0 && box.x < (kernel?.width ?? 0) && box.y > 0 && box.y < (kernel?.height ?? 0) };
  });
  return {
    mode: document.querySelector(".canvas-statusbar")?.textContent?.slice(0, 24),
    zoom: document.querySelector(".react-flow__viewport")?.style.transform,
    labels,
    chips,
  };
}

