async () => {
  await new Promise((resolve) => setTimeout(resolve, 900));
  const inspector = document.querySelector(".canvas-inspector")?.getBoundingClientRect();
  const kernel = document.querySelector(".architecture-canvas-kernel")?.getBoundingClientRect();
  return {
    docked: document.querySelector(".canvas-stage")?.className,
    kernelW: Math.round(kernel?.width ?? 0),
    inspector: inspector && { x: Math.round(inspector.x), w: Math.round(inspector.width), h: Math.round(inspector.height) },
    zoom: document.querySelector(".react-flow__viewport")?.style.transform,
    selected: document.querySelector(".object-node.is-selected")?.getAttribute("aria-label")?.slice(0, 30),
  };
}

