input.function:
async () => {
  const nodes = [...document.querySelectorAll(".object-node")];
  const target = nodes.find((node) => node.getAttribute("aria-label")?.includes("Evidence Agent")) ?? nodes[0];
  if (!target) return { error: "no nodes rendered", count: nodes.length };
  target.dispatchEvent(new MouseEvent("mouseover", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 700));
  return {
    target: target.getAttribute("aria-label"),
    renderedNodes: nodes.length,
    previewEdges: document.querySelectorAll(".relationship-edge.emphasis-preview").length,
    labels: [...document.querySelectorAll(".relationship-label")].map((label) => label.textContent).slice(0, 6),
  };
}

