async () => {
  document.querySelector(".object-node")?.dispatchEvent(new MouseEvent("mouseout", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 300));
  const zoomOut = [...document.querySelectorAll(".architecture-controls button")].find((button) => button.getAttribute("title")?.toLowerCase().includes("zoom out"));
  zoomOut.click();
  await new Promise((resolve) => setTimeout(resolve, 400));
  zoomOut.click();
  await new Promise((resolve) => setTimeout(resolve, 900));
  return {
    mode: document.querySelector(".canvas-statusbar")?.textContent?.slice(0, 24),
    zoom: document.querySelector(".react-flow__viewport")?.style.transform,
    regionKeys: [...document.querySelectorAll(".canvas-region-keys")].slice(0, 3).map((keys) => keys.textContent),
  };
}

